w Views/Partials/blockgrid/Components/blogPostListBlock.cshtml <<'EOF'
@inherits UmbracoViewPage<BlockGridItem<BlogPostListBlock>>
@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models.Blocks
@{
    var page = UmbracoContext.PublishedRequest?.PublishedContent;
    var posts = page?.Children<BlogPost>()?
        .OrderByDescending(p => p.PublishDate)
        .Select(p => new BlogPostSummaryModel
        {
            Title = p.Name,
            Summary = p.Summary ?? "",
            Url = p.Url(),
            ImageUrl = p.HeroImage?.GetCropUrl(width: 800, height: 450),
            Author = p.Author,
            PublishDate = p.PublishDate,
        })
        .ToList() ?? [];
    var model = new BlogPostListModel
    {
        Heading = Model.Content.Heading,
        Posts = posts,
    };
}
@await Component.InvokeAsync("BlogPostList", new { model })
EOF

# component views
w Views/Shared/Components/Hero/Default.cshtml <<'EOF'
@model Umbraco.Bench.Umbraco.Models.Blocks.HeroModel

<section class="relative isolate overflow-hidden bg-slate-900 text-white">
    @if (!string.IsNullOrEmpty(Model.ImageUrl))
    {
        <img src="@Model.ImageUrl" alt="" class="absolute inset-0 -z-10 h-full w-full object-cover opacity-40" />
    }
    <div class="mx-auto max-w-4xl px-6 py-24 sm:py-32">
        <h1 class="text-4xl font-bold tracking-tight sm:text-6xl">@Model.Heading</h1>
        @if (!string.IsNullOrEmpty(Model.Subheading))
        {
            <p class="mt-6 max-w-2xl text-lg text-slate-200">@Model.Subheading</p>
        }
    </div>
</section>
EOF
w Views/Shared/Components/RichText/Default.cshtml <<'EOF'
@model Umbraco.Bench.Umbraco.Models.Blocks.RichTextModel

<div class="mx-auto max-w-3xl px-6 py-4 text-lg leading-8 text-slate-700 [&_h2]:mt-8 [&_h2]:text-2xl [&_h2]:font-bold [&_h2]:text-slate-900 [&_p]:mt-4 [&_ul]:mt-4 [&_ul]:list-disc [&_ul]:pl-6 [&_li]:mt-2 [&_a]:text-indigo-600 [&_a]:underline">
    @Html.Raw(Model.Html)
</div>
EOF
w Views/Shared/Components/Image/Default.cshtml <<'EOF'
@model Umbraco.Bench.Umbraco.Models.Blocks.ImageModel

<figure class="mx-auto max-w-4xl px-6 py-6">
    <img src="@Model.ImageUrl" alt="@Model.Alt" class="w-full rounded-xl object-cover" loading="lazy" />
    @if (!string.IsNullOrEmpty(Model.Caption))
    {
        <figcaption class="mt-3 text-center text-sm text-slate-500">@Model.Caption</figcaption>
    }
</figure>
EOF
w Views/Shared/Components/Quote/Default.cshtml <<'EOF'
@model Umbraco.Bench.Umbraco.Models.Blocks.QuoteModel

<blockquote class="mx-auto my-6 max-w-3xl border-l-4 border-indigo-500 px-6 py-2">
    <p class="text-2xl font-semibold italic text-slate-800">&ldquo;@Model.Quote&rdquo;</p>
    @if (!string.IsNullOrEmpty(Model.Attribution))
    {
        <footer class="mt-3 text-sm text-slate-500">&mdash; @Model.Attribution</footer>
    }
</blockquote>
EOF
w Views/Shared/Components/BlogPostList/Default.cshtml <<'EOF'
@model Umbraco.Bench.Umbraco.Models.Blocks.BlogPostListModel

<section class="mx-auto max-w-5xl px-6 py-16">
    @if (!string.IsNullOrEmpty(Model.Heading))
    {
        <h2 class="text-3xl font-bold text-slate-900">@Model.Heading</h2>
    }
    <div class="mt-8 grid gap-8 md:grid-cols-2">
        @foreach (var post in Model.Posts)
        {
            <article class="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm transition hover:shadow-md">
                <a href="@post.Url" class="block">
                    @if (!string.IsNullOrEmpty(post.ImageUrl))
                    {
                        <img src="@post.ImageUrl" alt="" class="aspect-video w-full object-cover" loading="lazy" />
                    }
                    <div class="p-6">
                        <p class="text-sm text-slate-500">
                            @post.PublishDate.ToString("d MMMM yyyy")
                            @if (!string.IsNullOrEmpty(post.Author))
                            {
                                <span>&middot; @post.Author</span>
                            }
                        </p>
                        <h3 class="mt-2 text-xl font-semibold text-slate-900">@post.Title</h3>
                        <p class="mt-3 text-slate-600">@post.Summary</p>
                        <p class="mt-4 text-sm font-medium text-indigo-600">Read more &rarr;</p>
                    </div>
                </a>
            </article>
        }
    </div>
    @if (Model.Posts.Count == 0)
    {
        <p class="mt-8 text-slate-500">No posts yet.</p>
    }
</section>
EOF

# imports, layout, page templates
w Views/_ViewImports.cshtml <<'EOF'
@using Umbraco.Extensions
@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Cms.Web.Common.Views
@using Umbraco.Cms.Core.Models.PublishedContent
@using Microsoft.AspNetCore.Html
@addTagHelper *, Microsoft.AspNetCore.Mvc.TagHelpers
EOF
mkdir -p Views/Shared
w Views/Shared/_Layout.cshtml <<'EOF'
@inherits UmbracoViewPage
@{
    var siteName = Model.AncestorOrSelf<BlogFrontPage>()?.SiteName ?? "The MCP Blog";
    var pageTitle = ViewData["Title"] as string ?? Model.Name;
}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>@pageTitle &ndash; @siteName</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="bg-slate-50 text-slate-900 antialiased">
    <header class="border-b border-slate-200 bg-white">
        <div class="mx-auto flex max-w-5xl items-center justify-between px-6 py-4">
            <a href="@(Model.AncestorOrSelf<BlogFrontPage>()?.Url() ?? "/")" class="text-lg font-bold">@siteName</a>
        </div>
    </header>
    <main>
        @RenderBody()
    </main>
    <footer class="mt-16 border-t border-slate-200 bg-white py-8 text-center text-sm text-slate-500">
        &copy; @DateTime.Now.Year @siteName. Photos from Unsplash.
    </footer>
</body>
</html>
EOF
w Views/blogFrontPage.cshtml <<'EOF'
@inherits UmbracoViewPage<BlogFrontPage>
@{
    Layout = "_Layout.cshtml";
    ViewData["Title"] = Model.SiteName ?? Model.Name;
}
@await Html.GetBlockGridHtmlAsync(Model, "blocks")
EOF
w Views/blogPost.cshtml <<'EOF'
@inherits UmbracoViewPage<BlogPost>
@{
    Layout = "_Layout.cshtml";
    var heroUrl = Model.HeroImage?.GetCropUrl(width: 1800, height: 700);
}
<article>
    <header class="relative isolate overflow-hidden bg-slate-900 text-white">
        @if (!string.IsNullOrEmpty(heroUrl))
        {
            <img src="@heroUrl" alt="" class="absolute inset-0 -z-10 h-full w-full object-cover opacity-40" />
        }
        <div class="mx-auto max-w-3xl px-6 py-20">
            <p class="text-sm text-slate-300">
